#!/usr/bin/env python3
"""Replay hands generated by internal/holdem in PokerKit and compare.

PokerKit (University of Toronto, MIT licence, https://github.com/uoftcprg/pokerkit)
is used as a rules oracle in tests only; it is never shipped.

Input (stdin): one JSON object per line, written by crosscheck_test.go:
  {"id": 7, "sb": 10, "bb": 20, "ante": 0,
   "stacks": [..],            # starting stacks, hand order (index 0 left of the
                              # button, last index = button, as in PokerKit)
   "holes": ["AsKd", ..],     # hole cards per player
   "board": "2d3d4h9cJc",     # every board card the engine dealt
   "steps": [{"actor": 2, "call": 20, "fold": true, "raise": true,
              "min": 40, "max": 995, "act": "raise", "to": 995}, ..],
   "final": [..],             # engine's final stacks
   "pots": [305, 400],        # engine's pot amounts (main pot first)
   "showdown": true}          # cards were compared

For every decision it checks that PokerKit agrees on who acts, the amount
to call, whether folding/raising is allowed and the min/max raise-to. At the
end it compares final stacks and pot boundaries.

Odd chips: PokerKit merges pots once losing hands are killed and gives a
merged pot's whole remainder to the first winner. The engine splits each
pot separately and gives odd chips one each, clockwise from the button (the
usual card-room rule). Each PokerKit pot is re-divided that way over the
engine pots it spans before stacks are compared; such hands are counted as
"oddchip_adjusted". Excess antes or blinds nobody could match are returned
by both engines, so they never form a pot.

Output (stdout): a JSON line per failing hand, then {"summary": {...}}.
Run: python pokerkit_check.py < hands.jsonl
"""

import json
import sys
import warnings

from pokerkit import Automation, Mode, NoLimitTexasHoldem

AUTOMATIONS = (
    Automation.ANTE_POSTING,
    Automation.BET_COLLECTION,
    Automation.BLIND_OR_STRADDLE_POSTING,
    Automation.CARD_BURNING,
    Automation.HOLE_CARDS_SHOWING_OR_MUCKING,
    Automation.HAND_KILLING,
    Automation.CHIPS_PULLING,
)


def check(hand):
    errors = []
    n = len(hand["stacks"])
    st = NoLimitTexasHoldem.create_state(
        AUTOMATIONS,
        True,  # uniform antes count towards side pots
        hand["ante"],
        (hand["sb"], hand["bb"]),
        hand["bb"],
        tuple(hand["stacks"]),
        n,
        mode=Mode.TOURNAMENT,
    )
    board = hand["board"]
    dealt = 0  # board cards dealt to PokerKit
    steps = hand["steps"]
    k = 0
    pushes = []
    guard = 0
    while st.status:
        guard += 1
        if guard > 10000:
            errors.append("pokerkit loop did not finish")
            break
        if st.can_deal_hole():
            st.deal_hole(hand["holes"][st.hole_dealee_index])
        elif st.can_deal_board():
            count = 3 if dealt == 0 else 1
            cards = board[dealt * 2:(dealt + count) * 2]
            if len(cards) < count * 2:
                errors.append("pokerkit deals a street the engine never dealt")
                break
            st.deal_board(cards)
            dealt += count
        elif st.actor_index is not None:
            if k >= len(steps):
                errors.append(f"pokerkit waits for player {st.actor_index}; the engine hand had ended")
                break
            s = steps[k]
            k += 1
            where = f"step {k - 1}"
            if st.actor_index != s["actor"]:
                errors.append(f"{where}: actor pokerkit={st.actor_index} engine={s['actor']}")
                break
            call = st.checking_or_calling_amount
            if call != s["call"]:
                errors.append(f"{where}: call pokerkit={call} engine={s['call']}")
            if st.can_fold() != s["fold"]:
                errors.append(f"{where}: can fold pokerkit={st.can_fold()} engine={s['fold']}")
            lo = st.min_completion_betting_or_raising_to_amount
            hi = st.max_completion_betting_or_raising_to_amount
            if (lo is not None) != s["raise"]:
                errors.append(f"{where}: can raise pokerkit={lo is not None} engine={s['raise']}")
            elif lo is not None and (lo != s["min"] or hi != s["max"]):
                errors.append(f"{where}: raise range pokerkit={lo}-{hi} engine={s['min']}-{s['max']}")
            try:
                act = s["act"]
                if act == "fold":
                    st.fold()
                elif act in ("check", "call"):
                    st.check_or_call()
                elif act in ("bet", "raise"):
                    st.complete_bet_or_raise_to(s["to"])
                else:
                    errors.append(f"{where}: unknown action {act}")
                    break
            except (ValueError, UserWarning) as exc:
                errors.append(f"{where}: pokerkit rejected {act} {s.get('to', '')}: {exc}")
                break
        elif st.can_push_chips():
            pushes.append(list(st.push_chips().amounts))
        elif st.can_pull_chips():
            st.pull_chips()
        else:
            errors.append("pokerkit stalled")
            break
    if not errors:
        if k < len(steps):
            errors.append(f"the engine recorded {len(steps) - k} actions pokerkit never asked for")
        if dealt * 2 != len(board):
            errors.append(f"board: engine dealt {len(board) // 2} cards, pokerkit {dealt}")

    final = list(st.stacks)
    adjusted = False
    if hand.get("showdown") and not errors:
        # Pot boundaries: once losing hands are killed PokerKit merges pots
        # whose remaining players match, so each PokerKit pot must be a run of
        # consecutive engine pots. The engine splits every pot separately and
        # gives odd chips one each, clockwise from the button; PokerKit gives a
        # merged pot's whole remainder to the first winner. Re-divide each
        # PokerKit pot over the engine pots it spans before comparing stacks.
        go_pots = list(hand["pots"])
        g = 0
        for amounts in pushes:
            total = sum(amounts)
            parts, acc = [], 0
            while g < len(go_pots) and acc < total:
                parts.append(go_pots[g])
                acc += go_pots[g]
                g += 1
            if acc != total:
                errors.append(f"pots pokerkit={[sum(a) for a in pushes]} engine={go_pots}")
                break
            receivers = [i for i, a in enumerate(amounts) if a > 0]
            want = [0] * n
            for part in parts:
                q, r = divmod(part, len(receivers))
                for j, i in enumerate(receivers):
                    want[i] += q + (1 if j < r else 0)
            if want != list(amounts):
                adjusted = True
                final = [f - a + w for f, a, w in zip(final, amounts, want)]
        if not errors and g != len(go_pots):
            errors.append(f"pots pokerkit={[sum(a) for a in pushes]} engine={go_pots}")
    # Uncontested hands skip the pot check: PokerKit pushes only the dead
    # money and hands the winner's own bet back separately.
    if not errors and final != hand["final"]:
        errors.append(f"final stacks pokerkit={final} engine={hand['final']}")
    return errors, adjusted, final
    pk_pots = [sum(a) for a in pushes]
    go_prefix, total = set(), 0
    for amt in hand["pots"]:
        total += amt
        go_prefix.add(total)
    running = 0
    for amt in pk_pots:
        running += amt
        if not errors and running not in go_prefix:
            errors.append(f"pots pokerkit={pk_pots} engine={hand['pots']}")
            break
    if not errors and running != total:
        errors.append(f"pot total pokerkit={running} engine={total}")
    return errors, adjusted, final


def main():
    # PokerKit burns cards from its own deck, which can collide with the
    # engine's board; that only triggers a "not recommended" warning.
    warnings.filterwarnings("ignore", message=".*not recommended to be dealt.*")
    summary = {"hands": 0, "ok": 0, "failed": 0, "oddchip_adjusted": 0, "decisions": 0}
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        hand = json.loads(line)
        summary["hands"] += 1
        summary["decisions"] += len(hand["steps"])
        try:
            errors, adjusted, final = check(hand)
        except Exception as exc:  # report, keep going
            errors, adjusted, final = [f"exception: {exc!r}"], False, None
        if adjusted:
            summary["oddchip_adjusted"] += 1
        if errors:
            summary["failed"] += 1
            print(json.dumps({"id": hand["id"], "errors": errors, "pokerkit_final": final}))
        else:
            summary["ok"] += 1
    print(json.dumps({"summary": summary}))


if __name__ == "__main__":
    main()
